 function soundPlay(){if(!sound||!started||muted||paused()||soundPlaying)return;const current=sound,own=++soundToken;soundPlaying=true;current.play().then(playing=>{if(own===soundToken&&sound===current)soundPlaying=!!playing;}).catch(()=>{if(own!==soundToken||sound!==current)return;soundPlaying=false;$('.stories-sound').textContent='Som indisponível';});}
 function stopTick(){cancelAnimationFrame(raf);raf=0;lastTime=null;}
 function updateButtons(){$('.stories-prev').disabled=index===0;$('.stories-next').disabled=index===slides.length-1;$('.stories-position').textContent=(index+1)+' de '+slides.length;$('.stories-pause').textContent=userPaused?'Continuar':'Pausar';$('.stories-pause').setAttribute('aria-pressed',String(userPaused));$('.stories-sound').textContent=muted?'Ativar som':'Silenciar';$('.stories-sound').setAttribute('aria-pressed',String(!muted));metrics.index=index;metrics.total=slides.length;metrics.started=started;metrics.paused=paused();}
 function bars(){[...progress.children].forEach((bar,i)=>bar.value=i<index?1:i>index?0:slides[index]?.duration?Math.min(1,elapsed/slides[index].duration):started?1:0);}
 function tick(time){raf=0;if(paused()||!started)return;const duration=slides[index]?.duration;if(!duration)return;const delta=lastTime===null?0:Math.min(100,time-lastTime);lastTime=time;elapsed+=delta;metrics.elapsed=elapsed;bars();if(elapsed>=duration&&index<slides.length-1){go(index+1);return;}raf=requestAnimationFrame(tick);}
